import express, { Request, Response } from 'express';
import path from 'path';
import fs from 'fs';
import { createServer as createViteServer } from 'vite';

const app = express();
const PORT = 3000;

app.use(express.json({ limit: '15mb' }));
app.use(express.urlencoded({ extended: true }));

// Ensure data directory exists
const DB_DIR = path.join(process.cwd(), 'data');
const DB_FILE = path.join(DB_DIR, 'characters.json');

if (!fs.existsSync(DB_DIR)) {
  fs.mkdirSync(DB_DIR, { recursive: true });
}

function loadCharacters(): any[] {
  try {
    if (fs.existsSync(DB_FILE)) {
      const data = fs.readFileSync(DB_FILE, 'utf-8');
      const parsed = JSON.parse(data);
      if (Array.isArray(parsed)) {
        return parsed;
      }
    }
  } catch (err) {
    console.error('Error reading DB:', err);
  }
  return [];
}

function saveCharacters(chars: any[]) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(chars, null, 2), 'utf-8');
  } catch (err) {
    console.error('Error saving DB:', err);
  }
}

// ==========================================
// CHARACTER REST API
// ==========================================

// 1. GET /api/characters - Get all saved characters
app.get('/api/characters', (req: Request, res: Response) => {
  const { search, role, element } = req.query;
  let list = loadCharacters();

  if (search) {
    const term = String(search).toLowerCase();
    list = list.filter(
      (c) =>
        c.name?.toLowerCase().includes(term) ||
        c.cardDescription?.toLowerCase().includes(term) ||
        c.tags?.some((t: string) => t.toLowerCase().includes(term))
    );
  }

  if (role && role !== 'all') {
    list = list.filter((c) => c.role === role);
  }

  if (element && element !== 'all') {
    list = list.filter((c) => c.element === element);
  }

  res.json({
    success: true,
    data: list,
    total: list.length,
  });
});

// 2. GET /api/characters/:id - Get single character
app.get('/api/characters/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const list = loadCharacters();
  const char = list.find((c) => String(c.id) === String(id));

  if (!char) {
    return res.status(404).json({ success: false, error: 'Персонаж не найден' });
  }

  res.json({
    success: true,
    data: char,
  });
});

// 3. POST /api/characters - Create new character
app.post('/api/characters', (req: Request, res: Response) => {
  const payload = req.body;
  if (!payload.name || typeof payload.name !== 'string' || !payload.name.trim()) {
    return res.status(400).json({ success: false, error: 'Имя персонажа обязательно' });
  }

  const list = loadCharacters();
  const newId = payload.id ? String(payload.id) : String(Date.now());

  const newChar = {
    id: newId,
    name: payload.name.trim(),
    title: payload.title?.trim() || '',
    cardDescription: payload.cardDescription?.trim() || '',
    imageUrl: payload.imageUrl?.trim() || 'https://images.unsplash.com/photo-1568602471122-7832951cc4c5?w=400&auto=format&fit=crop&q=80',
    tags: Array.isArray(payload.tags) ? payload.tags : [],
    age: Number(payload.age) || 25,
    height: Number(payload.height) || 175,
    role: payload.role || 'Воин',
    element: payload.element || 'Огонь',
    lore: payload.lore?.trim() || '',
    stats: {
      strength: Number(payload.stats?.strength) || 70,
      agility: Number(payload.stats?.agility) || 70,
      intellect: Number(payload.stats?.intellect) || 70,
      defense: Number(payload.stats?.defense) || 70,
      magic: Number(payload.stats?.magic) || 50,
      regeneration: Number(payload.stats?.regeneration) || 60,
      hp: Number(payload.stats?.hp) || 120,
      maxHp: Number(payload.stats?.maxHp) || Number(payload.stats?.hp) || 120,
      mana: Number(payload.stats?.mana) || 60,
      maxMana: Number(payload.stats?.maxMana) || Number(payload.stats?.mana) || 60,
      level: Number(payload.stats?.level) || 1,
    },
    skills: Array.isArray(payload.skills) ? payload.skills : [],
    customStats: Array.isArray(payload.customStats) ? payload.customStats : [],
    connections: Array.isArray(payload.connections) ? payload.connections : [],
    createdAt: Date.now(),
    updatedAt: Date.now(),
  };

  list.unshift(newChar);
  saveCharacters(list);

  res.status(201).json({
    success: true,
    data: newChar,
    message: `Персонаж «${newChar.name}» успешно создан!`,
  });
});

// 4. PATCH /api/characters/:id - Update character
app.patch('/api/characters/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const list = loadCharacters();
  const index = list.findIndex((c) => String(c.id) === String(id));

  if (index === -1) {
    return res.status(404).json({ success: false, error: 'Персонаж не найден' });
  }

  const existing = list[index];
  const updates = req.body;

  list[index] = {
    ...existing,
    ...updates,
    stats: {
      ...existing.stats,
      ...(updates.stats || {}),
    },
    updatedAt: Date.now(),
  };

  saveCharacters(list);

  res.json({
    success: true,
    data: list[index],
    message: 'Персонаж успешно обновлен',
  });
});

// 5. DELETE /api/characters/:id - Delete character
app.delete('/api/characters/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  let list = loadCharacters();
  const exists = list.some((c) => String(c.id) === String(id));

  if (!exists) {
    return res.status(404).json({ success: false, error: 'Персонаж не найден' });
  }

  list = list.filter((c) => String(c.id) !== String(id));
  saveCharacters(list);

  res.json({
    success: true,
    message: `Персонаж удален`,
  });
});

// ==========================================
// VITE / STATIC SERVING
// ==========================================
async function startServer() {
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on port ${PORT}`);
  });
}

startServer();
